const config = {
  id_group: 'kelompok-00',
  default_node_count: 2,
  camera_timeout_ms: 70000,
  esp_timeout_ms: 25000,
  admin_username: 'admin',
  admin_password: 'admin123'
};
flow.set('smartMonitorConfig', config);
if (msg.status) {
  const text = String(msg.status.text || '').toLowerCase();
  msg.kind = 'broker_status';
  msg.connected = text.includes('connected') && !text.includes('disconnected');
  return [msg, null];
}
msg.kind = 'init';
msg.config = config;
const topics = [`${config.id_group}/node/register`];
for (let index = 1; index <= config.default_node_count; index++) {
  const node = `node-${String(index).padStart(2,'0')}`;
  topics.push(`${config.id_group}/${node}/detection/state`);
  topics.push(`${config.id_group}/${node}/camera/status`);
  topics.push(`${config.id_group}/${node}/esp32/status`);
}
return [msg, {action:'subscribe', topic:topics.map(topic=>({topic,qos:1}))}];

const config = flow.get('smartMonitorConfig');
if (!config) return null;
const COCO = ['person','bicycle','car','motorcycle','airplane','bus','train','truck','boat','traffic light','fire hydrant','stop sign','parking meter','bench','bird','cat','dog','horse','sheep','cow','elephant','bear','zebra','giraffe','backpack','umbrella','handbag','tie','suitcase','frisbee','skis','snowboard','sports ball','kite','baseball bat','baseball glove','skateboard','surfboard','tennis racket','bottle','wine glass','cup','fork','knife','spoon','bowl','banana','apple','sandwich','orange','broccoli','carrot','hot dog','pizza','donut','cake','chair','couch','potted plant','bed','dining table','toilet','tv','laptop','mouse','remote','keyboard','cell phone','microwave','oven','toaster','sink','refrigerator','book','clock','vase','scissors','teddy bear','hair drier','toothbrush'];
const COCO_SET = new Set(COCO), now = Date.now(), iso = new Date().toISOString();
let settings = context.get('settings') || {node_count:config.default_node_count};
let profiles = context.get('profiles') || [], runtime = context.get('runtime') || {};
let pending = context.get('pending') || {}, system = context.get('system') || {mqtt:false,sqlite:false};
let sessions = context.get('sessions') || {};
function save(){context.set('settings',settings);context.set('profiles',profiles);context.set('runtime',runtime);context.set('pending',pending);context.set('system',system);context.set('sessions',sessions)}
function ids(count=settings.node_count){return Array.from({length:Math.max(1,Number(count)||2)},(_,i)=>`node-${String(i+1).padStart(2,'0')}`)}
function base(id){return `${config.id_group}/${id}`}
function mqtt(topic,payload,retain=true){return {topic,payload:JSON.stringify(payload),qos:1,retain}}
function sql(op,topic,payload=[],extra={}){return {_op:op,topic,payload,...extra}}
function rules(value,mode){let obj=value;try{if(typeof obj==='string')obj=JSON.parse(obj)}catch{obj={}};if(!obj||Array.isArray(obj))return {};const out={};for(const [k,v] of Object.entries(obj)){if(!COCO_SET.has(k))continue;if(mode==='restricted')out[k]=true;else if(Number.isInteger(Number(v))&&Number(v)>=0&&Number(v)<=999)out[k]=Number(v)}return out}
function profile(row){const mode=row.mode==='threshold'?'threshold':'restricted';return {node_id:String(row.node_id),nama:String(row.nama||''),nim:String(row.nim||''),kelas:String(row.kelas||''),area:String(row.area||''),camera_name:String(row.camera_name||''),foto_base64:String(row.foto_base64||''),active:Number(row.is_active)!==0,mode,rules:rules(row.rules_json,mode),config_version:Number(row.config_version)||0}}
function evaluate(p,counts){
 const detail=[];
 // Evaluasi hanya kelas yang dikonfigurasi admin. Kelas lain pada payload
 // tidak ikut menentukan NORMAL/VIOLATION dan tidak dapat membatalkan alarm.
 if(p.mode==='restricted'){
  for(const name of Object.keys(p.rules)){
   const actual=Number(counts[name]||0);
   if(actual>0)detail.push({object:name,actual,rule:'dilarang'});
  }
 }else{
  for(const [name,rawMax] of Object.entries(p.rules)){
   const actual=Number(counts[name]||0),max=Number(rawMax);
   if(actual>max)detail.push({object:name,actual,rule:`maksimal ${max}`});
  }
 }
 return detail;
}
function snapshot(id){const p=profiles.find(x=>x.node_id===id),r=runtime[id]||{},camera=now-(r.camera_at||0)<config.camera_timeout_ms,esp=now-(r.esp_at||0)<config.esp_timeout_ms;let state='UNREGISTERED';if(p){if(!p.active)state='DISABLED';else if(!camera)state='OFFLINE';else state=r.state||'IDLE'}return {node_id:id,registered:!!p,nama:p?.nama||'',nim:p?.nim||'',kelas:p?.kelas||'',area:p?.area||'',camera_name:p?.camera_name||r.camera_name||'-',foto_base64:p?.foto_base64||'',active:p?.active??false,mode:p?.mode||'',rules:p?.rules||{},objects:r.objects||{},camera_online:camera,esp32_online:esp,state,detail:r.detail||[],event_id:r.event_id||'',updated_at:r.updated_at||null}}
function state(){const nodes=ids().map(snapshot);return {payload:{kind:'state',config:{id_group:config.id_group,coco:COCO},settings,nodes,pending,system:{...system,nodered:true},violations:nodes.filter(n=>n.state==='VIOLATION'),updated_at:iso}}}
function subscriptions(count=settings.node_count){const topics=[`${config.id_group}/node/register`];for(const id of ids(count)){topics.push(`${base(id)}/detection/state`,`${base(id)}/camera/status`,`${base(id)}/esp32/status`)}return [{action:'unsubscribe',topic:true},{action:'subscribe',topic:topics.map(topic=>({topic,qos:1}))}]}
function publishConfig(p){return mqtt(`${base(p.node_id)}/monitor/config`,{id_group:config.id_group,node_id:p.node_id,enabled:p.active,mode:p.mode,rules:p.rules,area:p.area,camera_name:p.camera_name,config_version:p.config_version,timestamp:iso})}
function transition(id,p,newState,detail){const r=runtime[id]||(runtime[id]={});if(r.state===newState&&JSON.stringify(r.detail||[])===JSON.stringify(detail))return [];
 const previous=r.state||'IDLE', out=[];r.state=newState;r.detail=detail;r.updated_at=iso;
 if(newState==='VIOLATION'&&previous!=='VIOLATION'){r.event_id=`${id}-${now}-${Math.random().toString(36).slice(2,7)}`;out.push(sql('event_open',`INSERT INTO violation_events(event_id,id_group,node_id,mode,started_at,objects_json,rules_json,details_json,status) VALUES(?,?,?,?,?,?,?,?, 'ACTIVE')`,[r.event_id,config.id_group,id,p.mode,iso,JSON.stringify(r.objects||{}),JSON.stringify(p.rules),JSON.stringify(detail)]));}
 if(previous==='VIOLATION'&&newState!=='VIOLATION'&&r.event_id){out.push(sql('event_close',`UPDATE violation_events SET ended_at=?,duration_seconds=CAST((julianday(?) - julianday(started_at))*86400 AS INTEGER),status='RESOLVED',end_reason=? WHERE event_id=?`,[iso,iso,newState,r.event_id]));r.event_id='';}
 out.push(mqtt(`${base(id)}/monitor/status`,{id_group:config.id_group,node_id:id,state:newState,detail,event_id:r.event_id||null,timestamp:iso}));
 out.push(mqtt(`${base(id)}/esp32/cmd`,{id_group:config.id_group,node_id:id,state:newState.toLowerCase(),alarm:newState==='VIOLATION',event_id:r.event_id||'',timestamp:iso}));return out}
function auth(p){const item=sessions[p.session_token];return !!item&&item.client_id===p.client_id&&item.until>now}
function feedback(ok,message,client_id='',extra={}){return {payload:{kind:'feedback',ok,message,client_id,...extra}}}
function refresh(extra={}){return sql('load_settings','SELECT node_count FROM monitoring_settings WHERE id_group=?',[config.id_group],extra)}

if(msg._op){system.sqlite=true;const op=msg._op;
 if(op==='create_nodes')return [sql('create_settings',`CREATE TABLE IF NOT EXISTS monitoring_settings(id_group TEXT PRIMARY KEY,node_count INTEGER NOT NULL DEFAULT 2,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)`),null,null,null,null];
 if(op==='create_settings')return [sql('create_events',`CREATE TABLE IF NOT EXISTS violation_events(event_id TEXT PRIMARY KEY,id_group TEXT,node_id TEXT,mode TEXT,started_at TEXT,ended_at TEXT,duration_seconds INTEGER,objects_json TEXT,rules_json TEXT,details_json TEXT,status TEXT,end_reason TEXT)`),null,null,null,null];
 if(op==='create_events')return [sql('seed_settings','INSERT OR IGNORE INTO monitoring_settings(id_group,node_count) VALUES(?,?)',[config.id_group,config.default_node_count]),null,null,null,null];
 if(['seed_settings','save_node','delete_node','save_count','toggle_node'].includes(op)){if(op==='save_node')pending={};save();return [refresh(msg._feedback?{_feedback:msg._feedback}:{}),null,null,null,null]}
 if(op==='load_settings'){const row=Array.isArray(msg.payload)?msg.payload[0]:null;if(row)settings.node_count=Math.min(30,Math.max(1,Number(row.node_count)||2));return [sql('load_nodes','SELECT * FROM monitoring_nodes WHERE id_group=? ORDER BY node_id',[config.id_group],{_feedback:msg._feedback}),null,null,null,null];}
 if(op==='load_nodes'){profiles=(Array.isArray(msg.payload)?msg.payload:[]).map(profile);save();const configs=profiles.map(p=>publishConfig(p));return [null,configs,state(),msg._feedback||null,subscriptions()];}
 if(op==='event_open'||op==='event_close'){save();return [null,null,state(),null,null]}
}
let p=msg.payload;
if(typeof p==='string'||Buffer.isBuffer(p)){try{p=JSON.parse(p.toString())}catch{return null}}
if(!p||typeof p!=='object'||Array.isArray(p))p=msg;
let kind=String(msg.kind||p.kind||'');
if(msg.topic&&typeof msg.topic==='string'&&!kind){
 const parts=msg.topic.split('/').filter(Boolean);
 if(msg.topic===`${config.id_group}/node/register`)kind='registration';
 else if(parts.length===4&&parts[0]===config.id_group&&String(p.node_id||'')===parts[1]){
  if(parts[2]==='detection'&&parts[3]==='state')kind='detection';
  else if(parts[2]==='camera'&&parts[3]==='status')kind='camera';
  else if(parts[2]==='esp32'&&parts[3]==='status')kind='esp32';
 }
}
if(['registration','camera','esp32','detection'].includes(kind)&&String(p.id_group||p.group_id||'')!==config.id_group)return null;
if(kind==='init'){runtime={};pending={};save();return [sql('create_nodes',`CREATE TABLE IF NOT EXISTS monitoring_nodes(id_group TEXT NOT NULL,node_id TEXT NOT NULL,nama TEXT NOT NULL,nim TEXT NOT NULL,kelas TEXT NOT NULL,area TEXT NOT NULL,camera_name TEXT NOT NULL,foto_base64 TEXT DEFAULT '',is_active INTEGER NOT NULL DEFAULT 1,mode TEXT NOT NULL DEFAULT 'restricted',rules_json TEXT NOT NULL DEFAULT '{}',config_version INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id_group,node_id))`),null,null,null,null]}
if(kind==='broker_status'){system.mqtt=!!msg.connected;save();return [null,null,state(),null,null]}
if(kind==='tick'){const outs=[];for(const pr of profiles){const snap=snapshot(pr.node_id);if(pr.active&&snap.state==='OFFLINE')outs.push(...transition(pr.node_id,pr,'IDLE',[]));}save();return [outs.filter(x=>x._op),outs.filter(x=>!x._op),state(),null,null]}
if(kind==='registration'){if(!ids().includes(p.node_id))return null;pending={node_id:p.node_id,event_id:p.event_id||'',received_at:iso};save();return [null,null,state(),feedback(true,`Permintaan registrasi ${p.node_id} diterima`),null]}
if(kind==='camera'){if(!ids().includes(String(p.node_id||'')))return null;const r=runtime[p.node_id]||(runtime[p.node_id]={});if(p.online!==false){r.camera_at=now;r.camera_name=String(p.camera_name||r.camera_name||'Webcam')}else r.camera_at=0;save();return [null,null,state(),null,null]}
if(kind==='esp32'){if(!ids().includes(String(p.node_id||'')))return null;const r=runtime[p.node_id]||(runtime[p.node_id]={});r.esp_at=p.online===false?0:now;r.esp_state=String(p.monitor_state||p.state||'online');save();return [null,null,state(),null,null]}
if(kind==='detection'){
 const pr=profiles.find(x=>x.node_id===p.node_id);if(!pr)return null;
 const r=runtime[p.node_id]||(runtime[p.node_id]={});r.detection_at=now;r.camera_at=now;r.objects={};
 for(const [name,count] of Object.entries(p.objects||{})){
  if(COCO_SET.has(name)&&Number.isInteger(Number(count))&&Number(count)>0)r.objects[name]=Number(count);
 }
 // Signature hanya memakai kelas aturan. Perubahan kelas lain tetap ditampilkan
 // pada dashboard, tetapi tidak mengubah status atau mematikan alarm.
 const monitoredCounts={};
 for(const name of Object.keys(pr.rules))monitoredCounts[name]=Number(r.objects[name]||0);
 const ruleSignature=JSON.stringify({version:pr.config_version,mode:pr.mode,counts:monitoredCounts});
 if(r.rule_signature===ruleSignature){save();return [null,null,state(),null,null]}
 r.rule_signature=ruleSignature;
 const detail=evaluate(pr,r.objects),next=!pr.active?'IDLE':(detail.length?'VIOLATION':'NORMAL');
 const outs=transition(pr.node_id,pr,next,detail);save();
 return [outs.filter(x=>x._op),outs.filter(x=>!x._op),state(),null,null];
}
if(kind==='login'){if(p.username===config.admin_username&&p.password===config.admin_password){const token=Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);sessions[token]={client_id:p.client_id,until:now+8*3600000};save();return [null,null,null,feedback(true,'Login berhasil',p.client_id,{session_token:token}),null]}return [null,null,null,feedback(false,'Username atau password salah',p.client_id),null]}
if(kind==='request_state')return [null,null,state(),null,null];
if(['save_node','delete_node','set_count','toggle_node'].includes(kind)&&!auth(p))return [null,null,null,feedback(false,'Sesi admin tidak valid',p.client_id),null];
if(kind==='set_count'){const count=Math.min(30,Math.max(1,Number(p.node_count)||2));return [sql('save_count','INSERT INTO monitoring_settings(id_group,node_count) VALUES(?,?) ON CONFLICT(id_group) DO UPDATE SET node_count=excluded.node_count,updated_at=CURRENT_TIMESTAMP',[config.id_group,count],{_feedback:feedback(true,'Jumlah node diperbarui',p.client_id)}),null,null,null,null]}
if(kind==='save_node'){const id=String(p.node_id||'');if(!ids().includes(id))return [null,null,null,feedback(false,'Node ID di luar jumlah node',p.client_id),null];const mode=p.mode==='threshold'?'threshold':'restricted',validRules=rules(p.rules,mode);if(!p.nama||!p.nim||!p.kelas||!p.area||!p.camera_name||!p.foto_base64||!Object.keys(validRules).length)return [null,null,null,feedback(false,'Nama, NIM, kelas, foto, area, kamera, dan aturan wajib lengkap',p.client_id),null];const version=now;pending={};save();return [sql('save_node',`INSERT INTO monitoring_nodes(id_group,node_id,nama,nim,kelas,area,camera_name,foto_base64,is_active,mode,rules_json,config_version) VALUES(?,?,?,?,?,?,?,?,1,?,?,?) ON CONFLICT(id_group,node_id) DO UPDATE SET nama=excluded.nama,nim=excluded.nim,kelas=excluded.kelas,area=excluded.area,camera_name=excluded.camera_name,foto_base64=excluded.foto_base64,mode=excluded.mode,rules_json=excluded.rules_json,config_version=excluded.config_version,updated_at=CURRENT_TIMESTAMP`,[config.id_group,id,String(p.nama),String(p.nim),String(p.kelas),String(p.area),String(p.camera_name),String(p.foto_base64),mode,JSON.stringify(validRules),version],{_feedback:feedback(true,`Data ${id} berhasil disimpan`,p.client_id)}),null,null,null,null]}
if(kind==='toggle_node'){const active=!!p.active;const pr=profiles.find(x=>x.node_id===p.node_id);if(!pr)return null;const outs=transition(pr.node_id,{...pr,active},active?'IDLE':'IDLE',[]);return [sql('toggle_node','UPDATE monitoring_nodes SET is_active=?,config_version=?,updated_at=CURRENT_TIMESTAMP WHERE id_group=? AND node_id=?',[active?1:0,now,config.id_group,pr.node_id],{_feedback:feedback(true,`${pr.node_id} ${active?'diaktifkan':'dinonaktifkan'}`,p.client_id)}),outs.filter(x=>!x._op),null,null,null]}
if(kind==='delete_node')return [sql('delete_node','DELETE FROM monitoring_nodes WHERE id_group=? AND node_id=?',[config.id_group,p.node_id],{_feedback:feedback(true,'Node dihapus',p.client_id)}),mqtt(`${base(p.node_id)}/monitor/config`,{id_group:config.id_group,node_id:p.node_id,enabled:false,mode:'restricted',rules:{},config_version:now,timestamp:iso}),null,null,null];
return null;

let statement=String(msg.topic||'');
if(!Array.isArray(msg.payload))msg.payload=[];
let index=0;
if(statement.includes('?')){
  statement=statement.replace(/\?/g,()=>'$p'+(++index));
  msg.topic=statement;
}
const placeholders=statement.match(/\$[A-Za-z_][A-Za-z0-9_]*/g)||[];
if(placeholders.length!==msg.payload.length){
  node.error(`Jumlah parameter SQLite tidak cocok: query ${placeholders.length}, data ${msg.payload.length}`,msg);
  return null;
}
return msg;

const text=String(msg.error?.message||msg.error||'');
let message='Operasi database gagal';
if(text.includes('UNIQUE'))message='Node ID tersebut sudah terdaftar';
else if(text.includes('locked'))message='SQLite sedang terkunci; coba kembali';
else if(text)message+=': '+text;
msg.payload={kind:'feedback',ok:false,client_id:msg._client_id||'',message};
return msg;
